update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p091","body":"غمِ ہستی سے معرفت کے لیے\nتجھے چنا تھا محبت کے لیے\n\nغیر سے توقع ہے ساتھ چلنے کی\nدوست کافی ہیں نصیحت کے لیے\n\nکیوں ناں اک بار پھر سے ملیں ہم\nابھی زندگی پڑی ہے فرقت کے لیے\n\nاب کہ اس شہر سے بھی دل بھر چلا ہے\nلوگ بہت آتے ہیں یہاں سیاحت کے لیے\n\nکبھی کچھ لمحوں کو جینا ہی زندگی ہے\nکبھی کچھ یادیں ہی کافی ہیں مسرت کے لیے\n\nبات ہم میں ہی نہ تھی کہ وہ اپنا کہتے\nفقط ایک دل ہی تھا وہ بھی حماقت کے لیے\n\nتمہارے بعد خوب نظر تان کے دیکھا احمد ؔ\nتم سا نہیں ملا کوئی چاہت کے لیے"},{"slug":"tum-p092","body":"نہ روشنی کی تلاش ہے\nنہ کوئی سُراغِ زندگی\nغمِ جہاں کی بات پھر کبھی\nغمِ زندگی ہے غمِ عاشقی\nہم سنجیدہ مزاج کے تھے آدمی\nہمیں راس نہ آئی دوستی\nجو دل جلا تو چل بسے\nہمیں یار ملے تھے کہ اجنبی\nیہ ساون ہی کی بات تھی\nایک یہی موسم تو یاد تھا\nبھیگے ہم تھے لب بام اور\nہر شخص آخر فرہاد تھا\nاور کیا ہی کسی کو یاد کریں\nایک شخص تھا اسے بھول گئے\nہم نے یاد رکھا کسی غیر کو\nجو عکس تھا اسے بھول گئے\nاسے کہنا تیرے بعد یہ شاعر لوگ\nفقط تجھ ہی پہ شعر سنائیں گے\nکہ لوٹ آئے گی یہ رت اگلے برس\nپر کبھی ہم نہ لوٹ کے آئیں گے"},{"slug":"tum-p093","body":"شب ہجر تم بن ہی اگر کاٹنی ہوتی\nکاش نہ چاند ہوتا نہ چاندنی ہوتی\n\nہم بھول چکے ہوتے اب تک\nتمہاری یاد اگر بھلانی ہوتی\n\nکبھی تم سے پہلے ملے ہوتے\nپھر یہ آرزو پرانی ہوتی\n\nکچھ حقیقوں کی تلخیاں ہوتیں\nکچھ سپنوں بھری کہانی ہوتی\n\nاحمد ؔ شاید ہم جو سننا چاہتے\nتم نے وہ بات سنانی ہوتی"},{"slug":"tum-p094","body":"مسکرا کے سارے غم سہتے ہو\nتم اس قدر کیوں چپ رہتے ہو\n\nجانے کیا بات دل میں کھٹکتی ہوگی\nجو بیٹھے بیٹھے سر پکڑتے ہو\n\nیہ غم بانٹنے سے بٹ بھی جاتا ہے\nبتاو! پھر کیوں اسے جمع کرتے ہو\n\nکچھ تم ہو آشنا کچھ میں بھی ہوں\nپھر بھی زمانے سے تنہا لڑتے ہو\n\nمیں نے بھی یہ عذاب راتیں کاٹی ہیں\nتم مجھ سے سب کچھ کہہ سکتے ہو\n\nرات سنسناتے پہر کی چلمن میں\nاحمد ؔ اچانک ہی تم اٹھ بیٹھتے ہو"},{"slug":"tum-p095","body":"اداس اداس رہنے لگا ہوں میں\nسب چپ کر کے سہنے لگا ہوں میں\n\nخود ہی جلا کے آشیانہ اپنا\nکرایے پے رہنے لگا ہوں میں\n\nشمع کو ہے روشنی کی امید\nاس قدر تو جلنے لگا ہوں میں\n\nکبھی ہوتا تھا نمایاں رخساروں پہ\nاب آنکھوں سے بہنے لگا ہوں میں\n\nکبھی اداسیوں سے ڈر لگتا تھا\nاب مسکراہٹیں سہنے لگا ہوں میں\n\nہاں تم ہی ہو اس کا عنوان\nوہ کتاب جو لکھنے لگا ہوں میں\n\nمجھ پہ ہوتا ہے شعروں کا نزول\nسب کی جو سننے لگا ہوں میں\n\nسنو آج کے لیے اتنا کافی تھا\nبہت ہوگیا اب رکنے لگا ہوں میں"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
